-- Banco de preguntas de la Autoevaluación, gestionable desde el panel (/admin/autoevaluaciones).
CREATE TABLE IF NOT EXISTS "preguntas_autoevaluacion" (
    "id" TEXT NOT NULL,
    "moduloSlug" TEXT NOT NULL,
    "amenazaSlug" TEXT,
    "tema" TEXT NOT NULL,
    "titulo" TEXT NOT NULL,
    "situacion" TEXT NOT NULL,
    "opciones" TEXT[],
    "correcta" INTEGER NOT NULL,
    "explicacion" TEXT NOT NULL,
    "orden" INTEGER NOT NULL DEFAULT 0,
    "activa" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "preguntas_autoevaluacion_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "preguntas_autoevaluacion_activa_orden_idx" ON "preguntas_autoevaluacion"("activa", "orden");

-- Precarga: las 24 preguntas que ya usaba la autoevaluación (lib/escenarios-data.ts),
-- con los mismos ids. ON CONFLICT evita duplicarlas si la migración se aplica de nuevo.
ON CONFLICT ("id") DO NOTHING;
